    {"claim": "Simultaneous and correlated exposure is undiversifiable, and the insurer's response to undiversifiable catastrophic exposure is not a new premium — it is exit.", "targets": ["insurance rebuttal to Skeptic AN-6"]},
    {"claim": "Full logs, no locatable defendant. Attribution dissolves precisely where the AI cannot cleanly identify whose principal it was acting for.", "targets": ["AN-9/AN-10 response"]},
    {"claim": "What is the rollback plan for a leaked genome, and who holds the authority to trigger it before the data is gone?", "targets": ["AN-8/AN-11 boundary", "AN-9/AN-10 response"]}
